const payload = $json.body ?? $json;
const event = String(payload.event ?? '').toLowerCase().replace(/[_-]/g, '.');
if (event !== 'messages.upsert') return [];

const data = payload.data ?? {};
const key = data.key ?? data.message?.key ?? {};
const remoteJid = String(key.remoteJid ?? data.remoteJid ?? '');
const deliveryJid = remoteJid.endsWith('@lid')
  ? String(key.remoteJidAlt ?? data.remoteJidAlt ?? remoteJid)
  : remoteJid;
const instance = String(payload.instance ?? payload.instanceName ?? '');

if (!instance || !remoteJid || key.fromMe === true) return [];
if (remoteJid.endsWith('@g.us') || remoteJid === 'status@broadcast' || remoteJid.includes('@newsletter')) return [];

const message = data.message ?? {};
const unwrapped = message.ephemeralMessage?.message ?? message.viewOnceMessage?.message ?? message;
const text = String(
  unwrapped.conversation ??
  unwrapped.extendedTextMessage?.text ??
  unwrapped.imageMessage?.caption ??
  unwrapped.videoMessage?.caption ??
  ''
).trim();
if (!text || !key.id) return [];

const number = deliveryJid.split('@')[0].replace(/\D/g, '');
if (!number) return [];

return [{
  json: {
    channel: 'whatsapp',
    instance,
    number,
    remoteJid,
    conversationId: `whatsapp:${instance}:${remoteJid}`,
    messageId: String(key.id),
    firstName: String(data.pushName ?? data.notifyName ?? '').slice(0, 80),
    language: 'pt-BR',
    text
  }
}];

const inbound = $('Normalizar e Filtrar Evento').first().json;
const result = $json;
if (result.duplicate === true || !Array.isArray(result.messages)) return [];

return result.messages
  .map((text) => String(text ?? '').trim())
  .filter(Boolean)
  .map((text, index) => ({
    json: {
      instance: inbound.instance,
      number: inbound.number,
      text: text.slice(0, 4000),
      delay: Math.min(2500, Math.max(900, 700 + text.length * 7)),
      order: index
    }
  }));
